/* A request frame's payload: `params` is decoded by the method's reader. */
typedef struct de_ep_request {
    uint64_t id;
    de_ep_str method;
    de_ep_raw params;
} de_ep_request;

bool de_ep_read_request(const char *payload, size_t len, de_ep_request *out);

/* Response and notification envelopes. Between begin and end, write the
 * result or data value (or use the typed writers below). */
